script:
frappe.ui.form.on('Correspond File', {
    refresh: function(frm) {
        console.log("[DEBUG] Correspond File form refreshed.");
        frm.clear_custom_buttons();

        if (!frm.is_new()) {
            frappe.call({
                method: 'correspond.correspond.doctype.correspond_file.correspond_file.get_file_and_references',
                args: { file_name: frm.doc.name },
                callback: function(r) {
                    if (!r.message) return;
                    let notes = r.message.notes || [];
                    let daks = r.message.daks || [];
                    let has_draft = notes.some(n => n.docstatus === 0);

                    render_eoffice_view(frm, notes, daks, has_draft);

                    if (!has_draft) {
                        frm.add_custom_button('Add Note', () => {
                            frappe.new_doc('Correspond Noting', { file: frm.doc.name });
                        }, 'Actions');
                    }

                    frm.add_custom_button('Create Outgoing Dak', () => {
                        frappe.new_doc('Correspond Dak', { type: 'Outward', linked_files: [{ file: frm.doc.name }] });
                    }, 'Actions');

                    frm.add_custom_button('Forward File', () => {
                        console.log("[DEBUG] Forward File clicked");
                    }, 'Actions');
                }
            });
        }

        // --- GLOBAL CLICK INTERCEPTION FOR REFERENCES ---
        if (!frm._link_interceptor_attached) {
            frm._link_interceptor_attached = true;
            $(frm.wrapper).on('click', 'a', function(e) {
                let href = $(this).attr('href');
                if (href && (href.includes('#note-') || href.includes('#dak-'))) {
                    let hashIndex = href.indexOf('#');
                    let targetId = href.substring(hashIndex + 1);
                    let targetFileMatch = href.match(/\/correspond-file\/([^\#\?]+)/);
                    let targetFile = targetFileMatch ? targetFileMatch[1] : null;

                    // If clicking a link for the current file, handle scroll locally without reloading
                    if (!targetFile || targetFile === frm.doc.name) {
                        e.preventDefault();
                        scroll_to_target(targetId);
                    } else {
                        // If linking to another file, store target in sessionStorage before navigating
                        sessionStorage.setItem('eoffice_scroll_target', targetId);
                    }
                }
            });
        }
    }
});

function render_eoffice_view(frm, notes, daks, has_draft) {
    // --- 1. Render Green Sheet (Notes) ---
    let $wrapper = frm.get_field('notings_display').$wrapper;
    if ($wrapper) {
        let html = `<div class="eoffice-scroll-container" style="padding: 15px; background-color: #f4fdf8; border-radius: 8px; border: 1px solid #c3e6cb; height: 75vh; overflow-y: auto; position: relative;">
            <h4 style="color: #155724; text-align: center; border-bottom: 2px solid #155724; padding-bottom: 10px;">Green Sheet (Notings)</h4>`;
        
        if (has_draft) {
            html += `<div style="background-color: #fff3cd; color: #856404; padding: 8px; border-radius: 4px; font-size: 12px; text-align: center; margin-bottom: 15px; border: 1px solid #ffeeba;">
                ⚠️ <b>Locked:</b> Cannot add new notes while an existing note is in Draft state.
            </div>`;
        }

        if (notes.length > 0) {
            let note_counter = 1;
            notes.forEach(note => {
                let is_draft = note.docstatus === 0;
                let status_badge = is_draft 
                    ? `<button class="btn btn-xs btn-default edit-note-btn" data-note-name="${note.name}" style="float: right; margin-left: 10px; background-color: #fff; border: 1px solid #ddd;">Edit Note</button>
                       <span class="badge badge-warning" style="float: right;">Draft</span>`
                    : '<span class="badge badge-success" style="float: right;">Final</span>';
                       
                html += `
                    <div id="note-${note.name}" class="target-reference-item" style="margin-bottom: 20px; border-bottom: 1px solid #c3e6cb; padding-bottom: 15px; transition: background-color 0.8s ease;">
                        <div style="font-size: 12px; color: #155724; margin-bottom: 8px;">
                            <b style="font-size: 14px;">Note #${note_counter}</b> &nbsp;•&nbsp; 
                            <b>${note.owner}</b> • ${status_badge}
                        </div>
                        <div style="font-size: 14px; color: #333; background: #fff; padding: 10px; border-radius: 5px; border: 1px solid #e2e3e5;">${note.note_details}</div>
                    </div>`;
                note_counter++;
            });
        } else {
            html += `<p style="text-align: center; color: #777; margin-top: 20px;">No notings found on this file.</p>`;
        }
        html += `</div>`;
        $wrapper.html(html);
    }

    // --- 2. Render Correspondence (Daks) ---
    let $dak_wrapper = frm.get_field('dak_display').$wrapper;
    if ($dak_wrapper) {
        let dak_html = `<div class="eoffice-scroll-container" style="padding: 15px; background-color: #f8f9fa; border-radius: 8px; border: 1px solid #dee2e6; height: 75vh; overflow-y: auto; position: relative;">
            <h4 style="color: #343a40; text-align: center; border-bottom: 2px solid #343a40; padding-bottom: 10px;">Correspondence (Dak)</h4>`;
        
        if (daks.length > 0) {
            let dak_counter = 1;
            daks.forEach(dak => {
                dak_html += `
                    <div id="dak-${dak.name}" class="target-reference-item" style="margin-bottom: 20px; border-bottom: 1px solid #dee2e6; padding-bottom: 15px; background: #fff; padding: 10px; border-radius: 5px; border: 1px solid #ced4da; transition: background-color 0.8s ease;">
                        <div style="font-size: 12px; color: #495057; margin-bottom: 5px;">
                            <b>Dak #${dak_counter}</b> • <b>ID:</b> ${dak.name}
                        </div>
                        <div style="font-size: 14px; color: #333;"><b>Subject:</b> ${dak.subject || 'Untitled'}</div>
                    </div>`;
                dak_counter++;
            });
        } else {
            dak_html += `<p style="text-align: center; color: #777; margin-top: 20px;">No correspondence found linked to this file.</p>`;
        }
        dak_html += `</div>`;
        $dak_wrapper.html(dak_html);
    }

    // --- Check for stored scroll targets (supports cross-file or initial load) ---
    setTimeout(() => {
        let storedTarget = sessionStorage.getItem('eoffice_scroll_target');
        let hash = window.location.hash;
        let targetId = storedTarget || (hash ? hash.substring(1) : null);

        if (targetId) {
            sessionStorage.removeItem('eoffice_scroll_target');
            scroll_to_target(targetId);
        }
    }, 400);

    // --- Event delegation for editing notes ---
    if (!frm._edit_listener_attached) {
        frm._edit_listener_attached = true;
        $(frm.wrapper).on('click', '.edit-note-btn', function(e) {
            e.preventDefault();
            let note_name = $(this).attr('data-note-name');
            if (note_name) {
                edit_note_inline(frm, note_name);
            }
        });
    }
}

// --- ACCURATE CONTAINER-AWARE SCROLL FUNCTION ---
function scroll_to_target(targetId) {
    let $target = $('#' + targetId);
    if ($target.length) {
        let $container = $target.closest('.eoffice-scroll-container');
        if ($container.length) {
            // Calculate exact relative scroll position inside the scrollable container
            let containerTop = $container.scrollTop();
            let elementTop = $target.position().top;
            let targetScrollPos = containerTop + elementTop - ($container.height() / 2) + ($target.height() / 2);
            
            $container.animate({ scrollTop: targetScrollPos }, 500);
        } else {
            $target[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
        }

        // Highlight flash effect
        $target.css('background-color', '#fff3cd');
        setTimeout(() => {
            $target.css('background-color', 'transparent');
        }, 2000);
    }
}

// --- GLOBAL SCOPE FUNCTIONS ---

function edit_note_inline(frm, note_name) {
    let parent_file = frm.doc.name;

    frappe.db.get_value('Correspond Noting', note_name, 'note_details')
    .then(r => {
        let current_text = r.message ? r.message.note_details : '';
        
        let d = new frappe.ui.Dialog({
            title: 'Edit Draft Note',
            fields: [
                { 
                    label: '🔗 Quick Reference Tool', 
                    fieldname: 'ref_helper_html', 
                    fieldtype: 'HTML', 
                    options: `<div style="margin-bottom: 10px;"><button type="button" class="btn btn-xs btn-default" id="dialog-insert-ref-btn"><i class="fa fa-link"></i> Insert Reference Link</button></div>` 
                },
                { label: 'Note Details', fieldname: 'note_details', fieldtype: 'Text Editor', reqd: 1, default: current_text }
            ],
            size: 'large',
            primary_action_label: 'Save Changes',
            primary_action(values) {
                frappe.call({
                    method: 'frappe.client.set_value',
                    args: {
                        doctype: 'Correspond Noting',
                        name: note_name,
                        fieldname: 'note_details',
                        value: values.note_details
                    },
                    callback: function() {
                        frappe.msgprint({ title: 'Success', message: 'Note updated.', indicator: 'green' });
                        d.hide();
                        frm.reload();
                    }
                });
            }
        });

        d.show();

        setTimeout(() => {
            d.$wrapper.find('#dialog-insert-ref-btn').on('click', function(e) {
                e.preventDefault();
                show_popup_reference_dialog(parent_file, d);
            });
        }, 200);
    });
}

function show_popup_reference_dialog(file_name, parent_dialog) {
    frappe.call({
        method: 'correspond.correspond.doctype.correspond_file.correspond_file.get_file_and_references',
        args: { file_name: file_name },
        callback: function(r) {
            if (!r.message) return;
            
            let files = r.message.files || [file_name];
            let notes = r.message.notes || [];
            let daks = r.message.daks || [];

            let file_options = files.map(f => f === file_name ? `${f} (Current File)` : f);

            let ref_d = new frappe.ui.Dialog({
                title: 'Insert File Reference',
                fields: [
                    {
                        label: 'Reference Category',
                        fieldname: 'ref_category',
                        fieldtype: 'Select',
                        options: 'Note\nDak',
                        default: 'Note',
                        change: function() {
                            update_target_dropdown();
                        }
                    },
                    {
                        label: 'Select File',
                        fieldname: 'target_file',
                        fieldtype: 'Select',
                        options: file_options,
                        default: file_options[0],
                        change: function() {
                            update_target_dropdown();
                        }
                    },
                    {
                        label: 'Select Document',
                        fieldname: 'selected_doc',
                        fieldtype: 'Select',
                        options: [],
                        reqd: 1
                    },
                    {
                        label: 'Custom Link Text (Optional)',
                        fieldname: 'link_text',
                        fieldtype: 'Data',
                        description: 'E.g., "See Note #1" or "Refer to Letter". If blank, default label will be used.'
                    }
                ],
                primary_action_label: 'Insert Into Note',
                primary_action(values) {
                    let category = values.ref_category;
                    let raw_file_selection = values.target_file;
                    let actual_file = raw_file_selection.replace(' (Current File)', '');
                    let doc_name = values.selected_doc;

                    if (!doc_name) {
                        frappe.msgprint('Please select a valid document to reference.');
                        return;
                    }

                    let prefix = category === 'Note' ? 'note' : 'dak';
                    let url = `/app/correspond-file/${actual_file}#${prefix}-${doc_name}`;
                    let display_text = values.link_text ? values.link_text : `${category} (${doc_name})`;

                    let field = parent_dialog.fields_dict['note_details'];
                    if (field && field.quill) {
                        let range = field.quill.getSelection();
                        if (range && range.length > 0) {
                            field.quill.formatText(range.index, range.length, 'link', url);
                        } else {
                            let cursor_pos = range ? range.index : field.quill.getLength();
                            field.quill.insertText(cursor_pos, ` [${display_text}] `, 'link', url);
                        }
                    } else {
                        let current_val = parent_dialog.get_value('note_details') || '';
                        parent_dialog.set_value('note_details', current_val + ` <a href="${url}">[${display_text}]</a> `);
                    }
                    ref_d.hide();
                }
            });

            function update_target_dropdown() {
                let category = ref_d.get_value('ref_category');
                let raw_file = ref_d.get_value('target_file') || file_options[0];
                let selected_file = raw_file.replace(' (Current File)', '');
                
                let doc_options = [];

                if (category === 'Note') {
                    let file_notes = notes.filter(n => n.file === selected_file);
                    file_notes.forEach((note, index) => {
                        let text_only = $('<div>').html(note.note_details || '').text();
                        let snippet = text_only.length ? text_only.substring(0, 25) + '...' : '';
                        let label = `Note #${index + 1}: ${snippet} (${note.name})`;
                        doc_options.push({ label: label, value: note.name });
                    });
                } else {
                    let file_daks = daks.filter(d => d.file === selected_file || true);
                    file_daks.forEach(dak => {
                        let label = `Dak: ${dak.name} - ${dak.subject || 'Untitled'}`;
                        doc_options.push({ label: label, value: dak.name });
                    });
                }

                let select_field = ref_d.fields_dict['selected_doc'];
                select_field.df.options = doc_options.length > 0 ? doc_options.map(o => o.label) : ['No records found'];
                select_field.refresh();

                ref_d.doc_mapping = {};
                doc_options.forEach(o => {
                    ref_d.doc_mapping[o.label] = o.value;
                });
            }

            let original_action = ref_d.primary_action;
            ref_d.set_primary_action('Insert Into Note', function() {
                let values = ref_d.get_values();
                if (!values) return;
                let mapped_id = ref_d.doc_mapping ? ref_d.doc_mapping[values.selected_doc] : values.selected_doc;
                values.selected_doc = mapped_id;
                original_action(values);
            });

            ref_d.show();
            update_target_dropdown();
        }
    });
}

frappe.ui.form.on('Correspond Noting', {
    refresh: function(frm) {
        // Remove any existing custom reference button to prevent duplicates
        $(frm.wrapper).find('.custom-ref-btn-row').remove();

        // Create a dedicated reference insertion bar right underneath the text editor
        let $ref_container = $(`
            <div class="custom-ref-btn-row" style="margin-top: 10px; margin-bottom: 15px; padding: 10px; background: #f8f9fa; border: 1px dashed #ced4da; border-radius: 4px; display: flex; align-items: center; justify-content: space-between;">
                <span style="font-size: 12px; color: #6c757d;"><b>eOffice Tools:</b> Insert a hyperlinked reference to a previous note, dak, or attached file.</span>
                <button type="button" class="btn btn-sm btn-primary btn-insert-reference">
                    <i class="fa fa-link"></i> Insert Reference Link
                </button>
            </div>
        `);

        // Insert this bar right after the 'note_details' field wrapper
        let field_wrapper = frm.get_field('note_details').$wrapper;
        if (field_wrapper) {
            field_wrapper.after($ref_container);

            // Bind click event to open the reference dialog
            $ref_container.find('.btn-insert-reference').on('click', function() {
                show_inline_reference_dialog(frm);
            });
        }
    }
});

function show_inline_reference_dialog(frm) {
    let d = new frappe.ui.Dialog({
        title: 'Insert File Reference',
        fields: [
            { 
                label: 'Reference Type', 
                fieldname: 'ref_type', 
                fieldtype: 'Select', 
                options: 'Correspond Noting\nCorrespond Dak\nAttached File', 
                reqd: 1 
            },
            { 
                label: 'Select Target Document', 
                fieldname: 'ref_doc', 
                fieldtype: 'Dynamic Link', 
                options: 'ref_type', 
                reqd: 1,
                get_query: function() {
                    return {
                        filters: {
                            'file': frm.doc.file
                        }
                    };
                }
            },
            {
                label: 'Custom Link Text (Optional)',
                fieldname: 'link_text',
                fieldtype: 'Data',
                description: 'E.g., "See Note #2" or "Refer to Letter dt. 10.08.2026". If blank, the Doc ID will be used.'
            }
        ],
        primary_action_label: 'Insert Into Note',
        primary_action(values) {
            let url = `/app/${values.ref_type.toLowerCase().replace(' ', '-')}/${values.ref_doc}`;
            let display_text = values.link_text ? values.link_text : values.ref_doc;
            
            let field = frm.fields_dict['note_details'];
            if (field && field.quill) {
                let range = field.quill.getSelection();
                let cursor_pos = range ? range.index : field.quill.getLength();
                
                // Insert the formatted hyperlink directly into the Quill editor at cursor position
                field.quill.insertText(cursor_pos, ` [${display_text}] `, 'link', url);
            } else {
                // Fallback if quill instance isn't directly caught
                let current_val = frm.doc.note_details || '';
                frm.set_value('note_details', current_val + ` <a href="${url}" target="_blank">[${display_text}]</a> `);
            }
            d.hide();
        }
    });
    d.show();
}
